"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import {
  ApiError,
  getPublicCompetition,
  type PublicCompetitionOut,
} from "@/lib/api";
import { SkillAreaCard } from "@/components/competitions/SkillAreaCard";
import { previewText } from "@/components/competitions/format";
import { ApiErrorAlert } from "@/components/forms/ApiErrorAlert";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

export default function CompetitionSkillsPage() {
  const params = useParams<{ competitionId: string }>();
  const competitionId = params.competitionId;
  const router = useRouter();
  const [cycle, setCycle] = useState<PublicCompetitionOut | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      setLoading(true);
      try {
        const data = await getPublicCompetition(competitionId);
        if (cancelled) return;
        if (data.skills.length < 2) {
          const sole = data.skills[0]?.skillId;
          const qs = sole ? `?skillId=${encodeURIComponent(sole)}` : "";
          router.replace(`/competitions/${competitionId}/enter${qs}`);
          return;
        }
        setCycle(data);
        setError(null);
      } catch (err) {
        if (!cancelled && err instanceof ApiError) {
          setError(err);
          setCycle(null);
        } else if (!cancelled) {
          setError(
            new ApiError(0, {
              error: {
                code: "HTTP_ERROR",
                message: "Could not load competition",
                fields: [],
                traceId: "",
              },
            }),
          );
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [competitionId, router]);

  const blurb = previewText(cycle?.description, 220);

  return (
    <div className="bg-competitions-atmosphere min-h-[calc(100dvh-var(--site-header-height))]">
      <div className="mx-auto max-w-6xl px-4 py-12 sm:px-6 sm:py-16">
        <Button variant="link" className="h-auto min-h-11 px-0" asChild>
          <Link href="/competitions">← Back to competitions</Link>
        </Button>

        {loading ? (
          <p className="mt-8 text-sm text-muted-foreground" role="status">
            Loading skill areas…
          </p>
        ) : null}

        <ApiErrorAlert error={error} title="Competition unavailable" />

        {error && !cycle ? (
          <Alert variant="destructive" className="mt-6">
            <AlertTitle>Not open for registration</AlertTitle>
            <AlertDescription>
              This competition is not available for public registration right
              now.
            </AlertDescription>
          </Alert>
        ) : null}

        {cycle ? (
          <>
            <header className="animate-comp-fade mt-6 max-w-2xl space-y-3">
              <p className="text-xs font-semibold uppercase tracking-[0.16em] text-brand-blue/70">
                Choose a skill area
              </p>
              <h1 className="text-3xl font-bold tracking-tight text-primary sm:text-4xl">
                {cycle.name}
              </h1>
              {blurb ? (
                <p className="text-base leading-relaxed text-muted-foreground">
                  {blurb}
                </p>
              ) : null}
            </header>

            <div className="mt-8 h-px w-full bg-gradient-to-r from-brand-gold/80 via-border to-transparent" />

            <ul className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {cycle.skills.map((skill, index) => (
                <li key={skill.skillId}>
                  <SkillAreaCard
                    competitionId={competitionId}
                    skill={skill}
                    index={index}
                  />
                </li>
              ))}
            </ul>
          </>
        ) : null}
      </div>
    </div>
  );
}
