import Link from "next/link";
import type { PublicSkillOut } from "@/lib/api";
import { cn } from "@/lib/utils";

type SkillAreaCardProps = {
  competitionId: string;
  skill: PublicSkillOut;
  index?: number;
};

export function SkillAreaCard({
  competitionId,
  skill,
  index = 0,
}: SkillAreaCardProps) {
  return (
    <Link
      href={`/competitions/${competitionId}/enter?skillId=${encodeURIComponent(skill.skillId)}`}
      data-testid="skill-area-card"
      className={cn(
        "animate-comp-fade group relative flex min-h-28 flex-col justify-between overflow-hidden rounded-2xl bg-card p-5 ring-1 ring-border transition duration-300",
        "hover:-translate-y-1 hover:ring-brand-gold/60",
        "focus-visible:ring-2 focus-visible:ring-ring",
      )}
      style={{ animationDelay: `${0.07 * index}s` }}
    >
      <span
        className="absolute inset-x-0 top-0 h-0.5 bg-gradient-to-r from-brand-blue via-brand-gold to-brand-green opacity-80"
        aria-hidden
      />
      <div className="space-y-1.5">
        {skill.familyName ? (
          <p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">
            {skill.familyName}
          </p>
        ) : null}
        <h3 className="text-lg font-bold tracking-tight text-primary">
          {skill.name}
        </h3>
        {skill.number ? (
          <p className="text-sm text-muted-foreground">Skill {skill.number}</p>
        ) : null}
      </div>
      <p className="mt-4 text-sm font-semibold text-primary underline-offset-4 group-hover:underline">
        Continue →
      </p>
    </Link>
  );
}
